import { use, useCallback } from 'react'

import ConceptStagedContext from '@/contexts/panels/concepts/ConceptStagedContext'
import ConceptModalContext from '@/contexts/panels/concepts/modal/ConceptModalContext'
import ConceptModalDataContext from '@/contexts/panels/concepts/modal/ConceptModalDataContext'
import useDebounce from '@/lib/hooks/useDebounce'
import { normalizeConceptName } from '@/lib/concept/state/name'

import { hasTrueValue } from '@/lib/utils'

const useAddChildHandlers = (formChild, setFormChild, modifiedFields, setModifiedFields, originalChild) => {
  const { modifyConcept } = use(ConceptStagedContext)
  const { closeModal, setModalData } = use(ConceptModalContext)
  const { modalData } = use(ConceptModalDataContext)

  // Debounced function to update modalData (for validation and external components)
  const debouncedUpdateModalData = useDebounce(
    useCallback(
      (updatedChild, modified) => {
        setModalData(prev => ({ ...prev, child: updatedChild, modified }))
      },
      [setModalData]
    )
  )

  const handleStage = useCallback(
    event => {
      event.preventDefault()

      const { action, child, index } = modalData
      const normalizedChild = {
        ...child,
        name: normalizeConceptName(child.name),
      }

      modifyConcept({
        type: action,
        update: { child: normalizedChild, index },
      })

      closeModal(true)
    },
    [closeModal, modalData, modifyConcept]
  )

  const handleChange = useCallback(
    field => event => {
      const value = event.target.value
      const updatedChild = {
        ...formChild,
        [field]: value,
      }

      // Immediate UI update
      setFormChild(updatedChild)

      const fieldIsModified = updatedChild[field] !== originalChild[field]

      const updatedModifiedFields = { ...modifiedFields, [field]: fieldIsModified }
      setModifiedFields(updatedModifiedFields)

      const modified = hasTrueValue(updatedModifiedFields)

      // Debounced modalData update (for validation, Actions component, etc.)
      debouncedUpdateModalData(updatedChild, modified)
    },
    [originalChild, formChild, modifiedFields, setFormChild, setModifiedFields, debouncedUpdateModalData]
  )

  return {
    handleChange,
    handleStage,
  }
}

export default useAddChildHandlers
