import { use } from 'react'

import { createStagedActions } from '@/components/modal/concept/conceptModalUtils'

import ConceptStagedContext from '@/contexts/panels/concepts/ConceptStagedContext'
import ConceptModalContext from '@/contexts/panels/concepts/modal/ConceptModalContext'
import ConceptModalDataContext from '@/contexts/panels/concepts/modal/ConceptModalDataContext'

import { CONCEPT } from '@/lib/constants'
import { CONCEPT_STATE } from '@/lib/constants/conceptState.js'
import { hasTrueValue } from '@/lib/utils'

const { PARENT } = CONCEPT_STATE

const ChangeParentActions = () => {
  const { confirmReset, modifyConcept } = use(ConceptStagedContext)
  const { closeModal } = use(ConceptModalContext)
  const { modalData } = use(ConceptModalDataContext)

  // Handle case where modalData might be undefined
  const { isValid = false, modified = false, parent = '' } = modalData || {}

  const isModified = hasTrueValue(modified)
  const stageDisabled = !confirmReset && (!isModified || !isValid)

  const handleStage = () => {
    modifyConcept({
      type: PARENT,
      update: { field: CONCEPT.FIELD.PARENT, value: parent },
    })
    closeModal(true)
  }

  return createStagedActions({
    closeModal,
    confirmReset,
    modifyConcept,
    name: 'ChangeParentActions',
    onStage: handleStage,
    stageDisabled,
  })
}

export default ChangeParentActions
